-- Yapay zekâ ekipman talimat taslakları (12.11.2026) — 14 tip
-- canli-ekipman-qr-gunluk-bakim-teblig-12-11-2026.sql'DEN SONRA çalıştırın. Tekrar çalıştırılırsa aynı tipi ikinci kez eklemez.
-- Kütüphaneye 'YZ taslağı' olarak girer; o tipte makinesi olan firmada listede 'Talimatı ekle' çıkar.

USE `u2858154_mehse`;

INSERT INTO `talimat_sablonlari` (`user_id`, `baslik`, `kategori`, `ekipman_tipi`, `yz_taslak`, `dokuman_no`, `aciklama`, `kkdler`, `maddeler`, `bolumler`, `taahhut`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `users` WHERE `rol` = 'sahip' ORDER BY `id` LIMIT 1), 'TAVAN VİNCİ / GEZER KÖPRÜLÜ VİNÇ GÜVENLİ ÇALIŞMA TALİMATI', 'is_makineleri', 'Tavan Vinci / Gezer Köprülü Vinç', 1, 'YZ-TLM-001', 'Yapay zekâ taslağı — uzman tarafından gözden geçirilmeli', '[]', '[]', '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, tavan vincinin (gezer köprülü vinç) 6331 sayılı İş Sağlığı ve Güvenliği Kanunu, İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği ve TS ISO 9927-1 standardına uygun olarak güvenli kullanımını, günlük kontrollerini ve bakım emniyet esaslarını kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Darbelere ve düşen cisimlere karşı koruyucu baret (EN 397) kullanılmalıdır.\",\"Kaymaya ve ağır parça düşmelerine karşı çelik burunlu emniyet ayakkabısı (EN ISO 20345) giyilmelidir.\",\"Kesilme, aşınma ve halat temaslarına karşı koruyucu iş eldiveni (EN 388) takılmalıdır.\",\"Gürültü seviyesinin yüksek olduğu alanlarda kulak koruyucu (EN 352-1) kullanılmalıdır.\",\"Bakım ve yüksekte kontrol çalışmaları sırasında tam vücut emniyet kemeri (EN 361) ve yaşam hattı kullanılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Köprü kirişi, uç arabalar, raylar, yürüyüş tekerlekleri ve tamponlar görünür kırık, çatlak ve deformasyona karşı kontrol edilmelidir.\",\"Çelik halat ve uç bağlantıları; ezilme, tel kopması, korozyon ve tambur sarım düzgünlüğü açısından incelenmelidir.\",\"Kanca, emniyet mandalı, kanca bloğu ve kullanılacak sapanlar tanımlı yük kapasitesine uygunluk açısından kontrol edilmelidir.\",\"Kaldırma ve yürütme frenlerinin işlevselliği ile kumanda butonlarının doğruluğu boşta çalıştırılarak test edilmelidir.\",\"Aşırı yük limitörü, alt-üst hareket limit sviçleri ve acil durdurma (e-stop) butonunun çalışabilirliği kontrol edilmelidir.\",\"Yürüyüş ikaz alarmı, ikaz lambaları, kablo taşıma (feston) ve enerji besleme hatlarının takılmadan çalıştığı doğrulanmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Kaldırılacak yükün ağırlığı doğrulanmalı ve vincin güvenli kaldırma kapasitesini (SWL) aşan yükleme yapılmamalıdır.\",\"Kanca yükün tam merkezine getirilmeli, halata açı vererek eğik ve yan çekme yapılmamalıdır.\",\"Yük kaldırılmadan önce yerden 10-15 cm kadar yükseltilerek frenlerin yükü tutma emniyeti test edilmelidir.\",\"Yük hareketi esnasında sesli ve ışıklı ikazlar aktif olmalı, yükün altından veya güzergahından insan geçişine izin verilmemelidir.\",\"Kaldırma ve sapanlama operasyonlarında sadece yetkili sapancı ve işaretçi ile standart el hareketleri üzerinden iletişim kurulmalıdır.\",\"Yük taşınırken mümkün olan en düşük seviyede tutulmalı ve ani hareketlerden (sert kaldırma\\/durdurma) kaçınılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma tamamlandığında kanca güvenli bir yüksekliğe çekilmeli, vinç park pozisyonuna alınmalı ve kancada yük bırakılmamalıdır.\",\"Kumanda panosu emniyetli bir yere asılmalı ve vincin ana besleme şalteri kapatılmalıdır.\",\"Temizlik, bakım veya onarım işlemleri öncesinde ana enerji kesilmeli ve Kilitleme-Etiketleme (EKED) prosedürü uygulanmalıdır.\",\"Bakım yapılan alanın altı güvenlik şeridi ile çevrilmeli ve \'Bakım Var \\/ Çalışmayın\' ikaz levhaları asılmalıdır.\",\"Günlük kontrol sonuçları ve tespit edilen aksaklıklar Vinç İşletme ve Bakım Defterine kaydedilmelidir.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Vincin etiket kapasitesinin üzerinde aşırı yük kaldırılması veya yere gömülü\\/sıkışmış nesnelerin çekilmesi yasaktır.\",\"Vinç kancasında, sapanlarda veya kaldırılan yük üzerinde insan taşınması ve seyir ettirilmesi kesinlikle yasaktır.\",\"Yük asılı durumdayken vinç kumandasının veya çalışma alanının terk edilmesi yasaktır.\",\"Emniyet sviçlerinin, limit anahtarlarının veya aşırı yük koruma sistemlerinin devre dışı bırakılması yasaktır.\",\"Hasarlı, deforme olmuş veya etiketi okunmayan sapan, kilit ve kaldırma aparatlarının kullanılması yasaktır.\",\"Yetki belgesi olmayan kişilerin vinç kullanması ve teknik personelin dışında kimsenin arızaya müdahale etmesi yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma esnasında beklenmeyen ses, titreşim, halat kayması veya kontrol kaybı durumunda derhal Acil Stop butonuna basılmalıdır.\",\"Fren arızası durumunda yükün düşme riskine karşı çalışma alanı acilen boşaltılmalı ve çevre emniyete alınmalıdır.\",\"Arızalanan vinç derhal stop edilmeli, ana şalter kapatılarak EKED kilidi vurulmalı ve üzerine \'ARIZALI - KULLANMAYIN\' etiketi asılmalıdır.\",\"Meydana gelen arıza, kaza veya ramak kala olayları vakit kaybetmeksizin bölüm amirine ve İSG Birimine bildirilmelidir.\",\"Yetkili teknik servis tarafından kontrol edilip \'Güvenli Kullanım Onayı\' verilmeden arızalı vinç tekrar devreye alınmamalıdır.\"]}]', 'Bu talimatı okudum, anladım ve iş sağlığı ve güvenliği kurallarına uygun şekilde çalışacağımı kabul ederim.', NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'Tavan Vinci / Gezer Köprülü Vinç');

INSERT INTO `talimat_sablonlari` (`user_id`, `baslik`, `kategori`, `ekipman_tipi`, `yz_taslak`, `dokuman_no`, `aciklama`, `kkdler`, `maddeler`, `bolumler`, `taahhut`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `users` WHERE `rol` = 'sahip' ORDER BY `id` LIMIT 1), 'PORTAL VİNÇ GÜVENLİ ÇALIŞMA TALİMATI', 'is_makineleri', 'Portal Vinç', 1, 'YZ-TLM-002', 'Yapay zekâ taslağı — uzman tarafından gözden geçirilmeli', '[]', '[]', '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, portal vincin güvenli bir şekilde işletilmesi, operatör ve çevre güvenliğinin sağlanması ile olası iş kazalarının önlenmesi amacıyla 6331 sayılı İş Sağlığı ve Güvenliği Kanunu ve TS ISO 9927-1 standardına uygun olarak hazırlanmıştır.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma sahasında çelik burunlu koruyucu iş ayakkabısı (EN ISO 20345) giyilmelidir.\",\"Çene bantlı endüstriyel emniyet baret (EN 397) kullanılmalıdır.\",\"Mekanik risklere karşı koruyucu iş eldiveni (EN 388) takılmalıdır.\",\"Yüksek gürültülü ortamlarda kulak koruyucu (EN 352-2) kullanılmalıdır.\",\"Saha içi görünürlüğü sağlamak amacıyla yüksek görünürlüklü ikaz yeleği (EN ISO 20471) giyilmelidir.\",\"Kiriş ve ray üzerindeki bakım veya kontrol çalışmalarında tam vücut emniyet kemeri (EN 361) kullanılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Kiriş, ayak ve ana bağlantı elemanlarında görünür çatlak, korozyon veya gevşeklik kontrolü yapılmalıdır.\",\"Raylar, yürüyüş tekerlekleri ve stoper tamponların görünür şekilde sağlam ve hasarsız olduğu doğrulanmalıdır.\",\"Çelik halat ve uç bağlantıları ezilme, kopuk tel ve deformasyon açısından denetlenmelidir.\",\"Tambur, makaralar, halat sarım düzeni ve halat kılavuzunun uygunluğu kontrol edilmelidir.\",\"Kanca, emniyet mandalı ve blok sağlam olmalı; sapanlar tanımlı ve yüke uygun seçilmelidir.\",\"Kaldırma ve yürütme frenleri ile kumandaların fonksiyonları yüksüz deneme ile test edilmelidir.\",\"Yük kapasite sınırlayıcıları, alt-üst limit anahtarları ve hareket sınırlandırıcılar kontrol edilmelidir.\",\"Acil durdurma butonu, ikaz sirenleri, tepe lambası ve kablo taşıma sistemleri kontrol edilmelidir.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Portal vincin beyan edilen azami kaldırma kapasitesi kesinlikle aşılmamalıdır.\",\"Yükler yalnızca dik olarak kaldırılmalı, halat yıpranmasına yol açan çapraz çekim yapılmamalıdır.\",\"Yükün taşınma güzergahında kimsenin bulunmadığından emin olunmalı, yük insan üzerinden geçirilmemelidir.\",\"Kaldırma ve yürütme işlemleri sırasında ani ivmelenme ve ani duruşlardan kaçınılmalıdır.\",\"Operatör, işaretçi ile sadece standart el işaretleri veya telsiz kullanarak iletişim kurmalıdır.\",\"Rüzgar hızı güvenli çalışma limitini aştığında kaldırma işlemi derhal durdurulmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma bitiminde vinç belirlenmiş emniyetli park konumuna çekilmeli ve ray fırtına klipsleri sabitlenmelidir.\",\"Kanca boşa alınmalı ve güvenli tutma yüksekliğine kadar yukarı çekilmelidir.\",\"Kumanda panosundan acil stop butonuna basılmalı ve ana besleme şalteri kapatılmalıdır.\",\"Bakım, onarım ve temizlik işlemleri öncesinde kilitlenme-etiketlenme (EKED\\/LOTO) prosedürü uygulanmalıdır.\",\"Çalışma alanı temizlenmeli, sapan ve ek teçhizatlar düzenli bir şekilde depolanmalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Portal vinç ile insan taşınması veya yük üzerinde personel bulunması kesinlikle yasaktır.\",\"Askıdaki yükün altında durmak, yürümek veya çalışma yapmak yasaktır.\",\"Yük sınırlandırıcılar, limit anahtarları ve emniyet donanımları devreden çıkarılarak çalışılamaz.\",\"Halatında ezilme veya kopuk tel bulunan, freni arızalı ekipmanla çalışma yapılması yasaktır.\",\"Vinç askıda yük varken başıboş bırakılmamalı ve terk edilmemelidir.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Herhangi bir tehlike anında acil durdurma (Emergency Stop) butonuna derhal basılmalıdır.\",\"Anormal ses, titreşim veya mekanik arıza durumunda sistem ana enerjisi kesilip vinç durdurulmalıdır.\",\"Tüm arıza ve tehlikeli durumlar vakit kaybetmeksizin birim amirine ve İSG uzmanına bildirilmelidir.\",\"Meydana gelen kaza veya ramak kala olaylarında saha emniyete alınarak yetkililere haber verilmelidir.\",\"Arızalara yetkisiz kişilerce müdahale edilmemeli, müdahale sadece yetkili bakım personeli tarafından yapılmalıdır.\"]}]', 'Bu talimatı okudum, anladım ve iş sağlığı ve güvenliği kurallarına uygun şekilde çalışacağımı kabul ederim.', NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'Portal Vinç');

INSERT INTO `talimat_sablonlari` (`user_id`, `baslik`, `kategori`, `ekipman_tipi`, `yz_taslak`, `dokuman_no`, `aciklama`, `kkdler`, `maddeler`, `bolumler`, `taahhut`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `users` WHERE `rol` = 'sahip' ORDER BY `id` LIMIT 1), 'MOBİL VİNÇ / HİYAP GÜVENLİ ÇALIŞMA TALİMATI', 'is_makineleri', 'Mobil Vinç / Hiyap', 1, 'YZ-TLM-003', 'Yapay zekâ taslağı — uzman tarafından gözden geçirilmeli', '[]', '[]', '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, 6331 sayılı İş Sağlığı ve Güvenliği Kanunu ile İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği ve TS ISO 9927-1 \\/ FEM standartlarına uygun olarak mobil vinç ve hiyap ekipmanlarının güvenli bir şekilde işletilmesi, kontrolü, bakımı ve olası iş kazalarının önlenmesi amacıyla hazırlanmıştır.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Baret (EN 397)\",\"Emniyet Ayakkabısı (EN ISO 20345 - S3 Çelik Burunlu ve Tabanlı)\",\"Yüksek Görünürlüklü İkaz Yeleği\\/Kıyafeti (EN ISO 20471 Class 2\\/3)\",\"Mekanik Risk Karşıtı İş Eldiveni (EN 388)\",\"Göz Koruyucu İkaz Gözlüğü (EN 166)\",\"Kulak Koruyucu (Gürültülü alanlarda EN 352-2)\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Motor ve hidrolik sıvı seviyeleri kontrol edilmeli, hortumlar ile silindirlerde sızıntı veya kaçak bulunmadığı doğrulanmalıdır.\",\"Lastik basınçları, jantlar, bijon somunları sağlam olmalı; fren sistemi ve direksiyon mekanizmasının çalışırlığı test edilmelidir.\",\"Bom bölümleri, uzatma bağlantıları, pimler ve emniyet segmanlarının eksiksiz ve sağlam olduğu fiziki olarak incelenmelidir.\",\"Çelik halat görünür tel kopması, ezilme, kıvrılma ve korozyon yönünden denetlenmeli; tambur sarımı, makaralar ve uç bağlantıları uygun olmalıdır.\",\"Kanca, emniyet mandalı ve blok sağlam olmalı; sapanlar tanımlı, etiketli ve kaldırılacak yük kapasitesine uygun seçilmelidir.\",\"Denge ayakları ve altlıkları düzgün yerleştirilmeli; vinç sağlam ve çökme riski olmayan zeminde teraziye alınmalıdır.\",\"Karşı ağırlık ve ayak açıklığı yük tablosuna uygun ayarlanmalı; yük moment sınırlayıcı (LMI), göstergeler ve üst kanca limiti test edilmelidir.\",\"Kaldırma ve dönüş frenleri, kumandalar, acil durdurma, aydınlatma, alarmlar, görüş araçları, yangın söndürücü kontrol edilmeli; rüzgâr hızı, hat mesafesi ve işaretçi iletişimi emniyete alınmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Kaldırma ve taşıma operasyonları yalnızca yetkili ve sertifikalı operatör tarafından, eğitilmiş işaretçi\\/sapancı eşliğinde yürütülmelidir.\",\"Yük moment tablosunda belirtilen maksimum güvenli çalışma yükü (SWL) ve yarıçap sınırları hiçbir koşulda aşılmamalıdır.\",\"Yükler dik olarak kaldırılmalı; açılı kaldırma, yan çekme veya zeminde sürükleme işlemleri kesinlikle yapılmamalıdır.\",\"Kaldırılan yükün dönmesini veya salınım yapmasını engellemek amacıyla en az bir adet yönlendirme halatı (kılavuz ipi) kullanılmalıdır.\",\"Vinç çalışma ve tarama alanına yetkisiz kişilerin girmesini önlemek için saha emniyet şeridi ile çevrilmeli ve ikaz levhaları asılmalıdır.\",\"Rüzgâr hızı üretici talimatlarında belirtilen emniyet sınırını (örneğin 10 m\\/s) aştığında kaldırma operasyonu derhal durdurulmalıdır.\",\"Yük havada asılı durumdayken operatör kumanda başından veya vinç kabininden ayrılmamalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma tamamlandığında vinç bomu emniyetli konuma çekilmeli, kanca sabitlenmeli ve denge ayakları toplanmalıdır.\",\"Park freni çekilmeli, ana kumanda şalteri kapatılmalı, kabin kilitlenmeli ve anahtar yetkisiz kişilerin ulaşamayacağı yere bırakılmalıdır.\",\"Temizlik, bakım ve onarım işlemleri öncesinde ekipmanın tüm enerji kaynakları kesilmeli ve Kilitleme-Etiketleme (LOTO\\/EKED) sistemi uygulanmalıdır.\",\"Hidrolik sistemdeki artık basınç tamamen tahliye edilmeden hidrolik devreler üzerinde sökme veya bakım yapılmamalıdır.\",\"Günlük çalışma sonunda ekipman genel görünüş kontrolünden geçirilmeli, biriken yağ ve kirden arındırılmalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Personel taşıma amacına uygun tasarlanmamış kanca veya yük üzerinde insan taşınması kesinlikle yasaktır.\",\"Kaldırılan veya asılı duran yükün altında durmak, yürümek ya da çalışma yapmak yasaktır.\",\"Yük moment sınırlayıcısı (LMI), ikaz alarmları veya üst kanca limit anahtarı devre dışı bırakılarak çalışılması yasaktır.\",\"Zemin yapısı incelenmeden, dolgu veya kuyu yakınlarında altlık kullanmaksızın denge ayaklarının basılması yasaktır.\",\"Yüksek gerilim ve enerji nakil hatlarına güvenli yaklaşma mesafesinden (en az 5 metre) fazla yaklaşılması yasaktır.\",\"Kapasite etiketi olmayan, deforme olmuş, yıpranmış veya hasarlı sapan ve bağlama ekipmanlarının kullanılması yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma sırasında anormal ses, hidrolik sızıntısı veya sistem arızası fark edildiğinde derhal \'ACİL STOP\' butonuna basılarak işlem durdurulmalıdır.\",\"Eğer yük havada iken arıza meydana gelirse, alan derhal tahliye edilmeli, güvenlik çemberine alınmalı ve yük emniyetli şekilde indirilmeye çalışılmalıdır.\",\"Arızalı veya güvensiz durumdaki vinç üzerine \'ARIZALIDIR - KULLANILMAZ\' ikaz etiketi asılmalı ve çalıştırma anahtarı sökülmelidir.\",\"Meydana gelen arıza, iş kazası veya ramak kala olayları vakit kaybetmeksizin Vardiya Amirine ve İSG Birimine bildirilmelidir.\",\"Arıza giderimi ve yetkisiz müdahaleler engellenmeli, onarım işlemleri sadece yetkili teknik servis personeli tarafından gerçekleştirilmelidir.\"]}]', 'Bu talimatı okudum, anladım ve iş sağlığı ve güvenliği kurallarına uygun şekilde çalışacağımı kabul ederim.', NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'Mobil Vinç / Hiyap');

INSERT INTO `talimat_sablonlari` (`user_id`, `baslik`, `kategori`, `ekipman_tipi`, `yz_taslak`, `dokuman_no`, `aciklama`, `kkdler`, `maddeler`, `bolumler`, `taahhut`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `users` WHERE `rol` = 'sahip' ORDER BY `id` LIMIT 1), 'ARAÇ KALDIRMA LİFTİ GÜVENLİ ÇALIŞMA TALİMATI', 'is_makineleri', 'Araç Kaldırma Lifti', 1, 'YZ-TLM-004', 'Yapay zekâ taslağı — uzman tarafından gözden geçirilmeli', '[]', '[]', '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, araç kaldırma liftinin 6331 sayılı İSG Kanunu, İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği ve TS EN 1493 standardına uygun olarak güvenli kullanımını, periyodik kontrollerini ve bakım esaslarını kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Mekanik risklere karşı koruyucu iş eldiveni (TS EN 388) kullanılmalıdır.\",\"Çelik burunlu ve kaymaz tabanlı emniyet ayakkabısı (TS EN ISO 20345) giyilmelidir.\",\"Sıvı sıçramalarına ve parçacıklara karşı koruyucu gözlük (TS EN 166) takılmalıdır.\",\"Baş yaralanmaları riskine karşı koruyucu baret (TS EN 397) kullanılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Kaldırma liftinin yıllık periyodik kontrol etiketinin güncel olduğu kontrol edilmelidir.\",\"Lift kollarındaki kauçuk kaldırma pabuçlarının yıpranmadığı ve sağlam olduğu doğrulanmalıdır.\",\"Mekanik güvenlik kilitleri, hidrolik hortumlar ve pabuç sabitleme pimleri gözle kontrol edilmelidir.\",\"Acil stop butonunun ve sesli ikaz sisteminin çalışırlığı test edilmelidir.\",\"Lift etrafındaki çalışma sahası yağ, gres ve takılmaya sebep olacak malzemelerden temizlenmelidir.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Araç, lift kollarının tam ortasına gelecek şekilde konumlandırılmalı ve kaldırma noktaları üretici talimatlarına göre ayarlanmalıdır.\",\"Araç tekerlekleri yerden 10-15 cm kaldırıldıktan sonra durdurulmalı ve aracın dengede olduğu sallanma testi ile doğrulanmalıdır.\",\"Araç istenen yüksekliğe kaldırıldıktan sonra mekanik emniyet kilitleri (stoperler) mutlaka devreye sokulmalıdır.\",\"Lift kilitlenmeden ve mekanik güvenlik tam sağlanmadan araç altında kesinlikle çalışılmamalıdır.\",\"Liftin azami taşıma kapasitesi (tonajı) hiçbir koşulda aşılmamalıdır.\",\"Kaldırma ve indirme işlemleri esnasında hareketli aksamların yakınında durulmamalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma tamamlandığında araç emniyetli bir şekilde zemin seviyesine indirilmeli ve lift kolları serbest konuma getirilmelidir.\",\"Lift panosundaki ana şalter kapatılmalı ve sistem enerjisi kesilmelidir.\",\"Bakım, onarım ve temizlik işlemleri öncesinde etiketleme ve kilitleme (EKED\\/LOTO) prosedürü uygulanmalıdır.\",\"Taşıyıcı kollar ve zemin hidrolik yağ ve kirden temizlenmelidir.\",\"Hidrolik yağ seviyesi ve kaçak durumu periyodik olarak kontrol edilmelidir.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Araç lift üzerindeyken içinde insan veya canlı bulunması kesinlikle yasaktır.\",\"Mekanik emniyet kilitleri arızalı veya devre dışı bırakılmış lifterin kullanılması yasaktır.\",\"Lift hareketi esnasında araca müdahale edilmesi veya aracın üzerine çıkılması yasaktır.\",\"Yetkisiz ve eğitimi bulunmayan personelin lift kumanda panosunu kullanması yasaktır.\",\"Araç lift üzerindeyken aracın ağırlık merkezini ciddi şekilde değiştirecek ağır parça sökümlerinin desteksiz yapılması yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma sırasında anormal ses, sarsıntı veya hidrolik sızıntı tespit edildiğinde işlem derhal durdurulmalıdır.\",\"Acil bir durumda derhal acil stop butonuna basılmalı ve ana güç kaynağı kesilmelidir.\",\"Elektrik kesintisi veya arıza durumunda askıda kalan araç için yetkisiz kişilerce manuel indirme müdahalesi yapılmamalıdır.\",\"Tüm arıza ve güvensiz durumlar derhal İSG uzmanına ve teknik bakım sorumlusuna bildirilmelidir.\",\"Arızalı lift üzerine \'ARIZALIDIR - KULLANMAYINIZ\' uyarısı asılmalı ve kilitlenmelidir.\"]}]', 'Bu talimatı okudum, anladım ve iş sağlığı ve güvenliği kurallarına uygun şekilde çalışacağımı kabul ederim.', NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'Araç Kaldırma Lifti');

INSERT INTO `talimat_sablonlari` (`user_id`, `baslik`, `kategori`, `ekipman_tipi`, `yz_taslak`, `dokuman_no`, `aciklama`, `kkdler`, `maddeler`, `bolumler`, `taahhut`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `users` WHERE `rol` = 'sahip' ORDER BY `id` LIMIT 1), 'CARASKAL & HALATLI/ZİNCİRLİ ÇEKTİRME GÜVENLİ ÇALIŞMA TALİMATI', 'is_makineleri', 'Caraskal & Halatlı/Zincirli Çektirme', 1, 'YZ-TLM-005', 'Yapay zekâ taslağı — uzman tarafından gözden geçirilmeli', '[]', '[]', '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, caraskal ve zincirli\\/halatlı çektirme ekipmanlarının TS EN 13157 standardı ile İş Sağlığı ve Güvenliği Mevzuatına uygun şekilde güvenli kullanımını, günlük kontrollerini, çalışma ve bakım esaslarını kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Baret (TS EN 397)\",\"Mekanik risklere karşı koruyucu iş eldiveni (TS EN 388)\",\"Çelik burunlu emniyet ayakkabısı (TS EN ISO 20345)\",\"Koruyucu iş gözlüğü (TS EN 166)\",\"Yüksekte çalışma yapılan alanlarda tam vücut emniyet kemeri (TS EN 361)\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Üst askı noktası ve taşıyıcı elemanın yük kapasitesine uygunluğu kontrol edilmelidir.\",\"Üst ve alt kancaların sağlamlığı, emniyet mandallarının tam oturduğu ve yükün merkezden bağlandığı doğrulanmalıdır.\",\"Yük zincirinde bükülme, çatlak, belirgin aşınma, zincir dişlisi ve gövdede görünür hasar olup olmadığı incelenmelidir.\",\"El zinciri ve zincir kılavuzunun düzgün, takılmadan hareket ettiği kontrol edilmelidir.\",\"Yük freninin üretici talimatlarına uygun şekilde yükü güvenle tuttuğu ve gövde bağlantılarının sağlam olduğu test edilmelidir.\",\"Kapasite levhasının okunaklılığı, planlanan yükün kapasite dahilinde olduğu ve sapan aksesuarlarının uygunluğu doğrulanmalıdır.\",\"Çekişin düşey düzlemde olduğu, yük yolunun boş bırakıldığı ve yan çekme riskinin önlendiği teyit edilmelidir.\",\"Kaldırma alanı güvenlik şeridiyle ayrılmalı ve ekiple iletişim yöntemleri hazır hale getirilmelidir.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Yük kaldırma ve taşıma esnasında daima düşey doğrultuda çalışılmalı, yan çekme yapılmamalıdır.\",\"Kaldırma işlemine başlamadan önce yük birkaç santimetre kaldırılarak fren sisteminin tutuşu test edilmelidir.\",\"Yükün hareket yolu boyunca emniyetli bölgede durulmalı, askıdaki yükün altında veya salınım alanında kesinlikle bulunulmamalıdır.\",\"El zinciri veya çektirme kolu dengeli ve kademeli kuvvet uygulanarak çekilmeli, ani darbeli zorlamalardan kaçınılmalıdır.\",\"Yük havada asılı durumdayken caraskal ve çektirme kontrolü kesinlikle başıboş bırakılmamalıdır.\",\"Yükün çevre elemanlarına veya yapılara takılmaması için hareket güzergahı kesintisiz izlenmelidir.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma bitiminde yük tamamen emniyetli zemine indirilmeli ve kanca boşaltılmalıdır.\",\"Ekipman zincirleri, kancaları ve gövdesi kir, toz ve yağdan temizlenerek görsel kontrolden geçirilmelidir.\",\"Bakım, temizlik ve yağlama işlemleri öncesinde ekipman kilitlenmeli ve etiketlenmelidir (EKED).\",\"Caraskal ve çektirme aparatı nemden, korozif maddelerden ve fiziki darbelerden korunaklı belirlenmiş depolama alanına asılmalıdır.\",\"Periyodik bakım ve kontrol sonuçları yetkili ekipman sorumlusu tarafından bakım kayıtlarına işlenmelidir.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Ekipmanın üzerinde belirtilen azami güvenli çalışma yük kapasitesinin üzerinde yük kaldırılması yasaktır.\",\"Caraskal ve çektirme aparatları kullanılarak insan taşınması veya insanların kaldırılması kesinlikle yasaktır.\",\"Hasarlı, çatlak, bükülmüş zincirli veya emniyet mandalı arızalı ekipmanlarla çalışılması yasaktır.\",\"Yük zincirinin doğrudan sapan gibi yükün etrafına sarılarak bağlanması yasaktır.\",\"Askıda bulunan yükün altında durulması, geçilmesi veya yük altında çalışma yapılması yasaktır.\",\"Yetkisiz ve eğitimsiz personelin ekipmanı kullanması, bakım veya onarım yapması yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma sırasında anormal ses, fren kaçırma veya zincir takılması durumunda işlem derhal durdurulmalıdır.\",\"Yük imkan dahilindeyse emniyetli şekilde zemine indirilmeli, indirilemiyorsa alan derhal tahliye edilerek emniyet şeridine alınmalıdır.\",\"Ekipman üzerine \'ARIZALI - KULLANMAYIN\' uyarı etiketi asılarak kullanımı engellenmelidir.\",\"Meydana gelen arıza veya tehlikeli durum zaman kaybetmeden İş Güvenliği Uzmanına ve Bakım Sorumlusuna bildirilmelidir.\",\"Olası kaza veya ramak kala olaylarında ilk yardım ve acil durum ekiplerine haber verilerek olay yeri inceleme için korunmalıdır.\"]}]', 'Bu talimatı okudum, anladım ve iş sağlığı ve güvenliği kurallarına uygun şekilde çalışacağımı kabul ederim.', NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'Caraskal & Halatlı/Zincirli Çektirme');

INSERT INTO `talimat_sablonlari` (`user_id`, `baslik`, `kategori`, `ekipman_tipi`, `yz_taslak`, `dokuman_no`, `aciklama`, `kkdler`, `maddeler`, `bolumler`, `taahhut`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `users` WHERE `rol` = 'sahip' ORDER BY `id` LIMIT 1), 'TELESKOPİK YÜKLEYİCİ (MANİTOU / TELEHANDLER) GÜVENLİ ÇALIŞMA TALİMATI', 'is_makineleri', 'Teleskopik Yükleyici (Manitou / Telehandler)', 1, 'YZ-TLM-006', 'Yapay zekâ taslağı — uzman tarafından gözden geçirilmeli', '[]', '[]', '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, teleskopik yükleyicinin TS EN 1459-1 standardı ve ilgili mevzuata uygun olarak güvenli kullanımını, günlük kontrollerini, çalışma sırası ve sonrası güvenlik önlemlerini ve acil durum prosedürlerini kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Darbe ve düşen cisim risklerine karşı baret (EN 397) kullanılmalıdır.\",\"Kaymaya dirençli ve koruyucu burunlu iş ayakkabısı (EN ISO 20345) giyilmelidir.\",\"Mekanik risklere karşı koruyucu iş eldiveni (EN 388) kullanılmalıdır.\",\"Gürültü seviyesinin 80 dB(A) üzerine çıktığı durumlarda kulak koruyucu (EN 352-1) takılmalıdır.\",\"Tozlu ve parçacıklı ortamlarda koruyucu gözlük (EN 166) kullanılmalıdır.\",\"Saha içi görünürlüğü sağlamak amacıyla yüksek görünürlüklü ikaz yeleği (EN ISO 20471) giyilmelidir.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Motor yağı, soğutma sıvısı seviyeleri ile yakıt ve yağ sistemlerindeki kaçaklar kontrol edilmelidir.\",\"Hidrolik yağ seviyesi, hortumlar, silindirler ve bağlantılar sızıntı ve hasar yönünden incelenmelidir.\",\"Lastiklerin genel durumu, hava basınçları, jantlar ve bijonların sağlamlığı kontrol edilmelidir.\",\"Servis freni, park freni ve direksiyon sisteminin güvenli işlev kontrolü yapılmalıdır.\",\"Bom bölümleri, kayma pabuçları ve bağlantı pimlerinin eksiksiz ve sağlam olduğu doğrulanmalıdır.\",\"Çatal veya takılı ataşmanın sağlamlığı ve hızlı bağlantı mekanizmasının kilitli olduğu doğrulanmalıdır.\",\"Yük moment göstergesi, limit sınırlayıcılar, denge ayakları, ikaz lambaları, korna ve geri vites alarmının çalıştığı kontrol edilmelidir.\",\"Çalışma alanının zemini, kenar mesafeleri, yüksek gerilim hatları ve yaya yolları incelenerek makine terazide konumlandırılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Operatör koltuğunda otururken emniyet kemeri mutlaka takılı tutulmalıdır.\",\"Sürüş esnasında bom mümkün olduğunca geri çekilmeli ve yük zemine yakın konumda taşınmalıdır.\",\"Kaldırma ve uzanma işlemlerinde ataşmana uygun yük çizelgesi ve kapasite limitleri dışına çıkılmamalıdır.\",\"Yük moment göstergesi uyarıları dikkate alınmalı, emniyet sınırları zorlanmamalıdır.\",\"Denge ayakları kullanılacağı zaman sağlam altlıklar üzerinde ve zemin terazisindeyken tam açıklıkta sabitlenmelidir.\",\"Eğimli arazide sürüş yaparken yük daima yokuş yukarı yönde tutulmalıdır.\",\"Görüşün kısıtlı olduğu alanlarda veya hassas yanaşmalarda eğitimli bir işaretçi ile çalışılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma tamamlandığında araç emniyetli, düz ve sert bir zemine park edilmelidir.\",\"Teleskopik bom tamamen içeri çekilmeli, en alt seviyeye indirilerek ataşman zemine oturtulmalıdır.\",\"Park freni çekilmeli, vites nötr konuma getirilmeli ve motor durdurulmalıdır.\",\"Kontak anahtarı çıkarılarak yetkisiz kişilerin erişemeyeceği emniyetli bir yerde muhafaza edilmelidir.\",\"Bakım veya temizlik öncesinde enerji kesme ve tehlikeli enerji kilitleme-etiketleme (EKED\\/LOTO) prosedürü uygulanmalıdır.\",\"Hidrolik hatlardaki kalıntı basınç boşaltılmadan basınçlı aksamlara müdahale edilmemelidir.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Çatal veya ataşman üzerinde insan taşınması ve kaldırılması kesinlikle yasaktır.\",\"İmalatçı tarafından belirlenen maksimum yük ve uzanma kapasitesinin üzerinde kaldırma yapılması yasaktır.\",\"Yük kaldırılmış veya bom uzatılmış durumdayken makinenin yer değiştirmesi yasaktır.\",\"Yük moment göstergesi ve emniyet sviçlerinin devre dışı bırakılması yasaktır.\",\"Yüksek gerilim hatlarının emniyetli yaklaşma mesafesi sınırları içerisine bom uzatılması yasaktır.\",\"Kabin kapısı açıkken veya emniyet kemeri takılmadan aracın sürülmesi yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma esnasında hidrolik sızıntı veya fren arızası tespit edilirse işlem derhal durdurulmalıdır.\",\"Acil bir tehlike anında acil stop butonuna basılarak veya kontak kapatılarak araç durdurulmalıdır.\",\"Ekipmanda oluşan arıza veya güvensiz durumlar anında yetkili amire ve İş Sağlığı ve Güvenliği birimine bildirilmelidir.\",\"Arızalı ekipman üzerine \'KULLANIMI TEHLİKELİDİR\' etiketi asılarak kullanım dışı bırakılmalıdır.\",\"Yangın durumunda araç emniyetli bir yerde durdurulup motor stop edilmeli ve yangın söndürücü ile ilk müdahale yapılmalıdır.\"]}]', 'Bu talimatı okudum, anladım ve iş sağlığı ve güvenliği kurallarına uygun şekilde çalışacağımı kabul ederim.', NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'Teleskopik Yükleyici (Manitou / Telehandler)');

INSERT INTO `talimat_sablonlari` (`user_id`, `baslik`, `kategori`, `ekipman_tipi`, `yz_taslak`, `dokuman_no`, `aciklama`, `kkdler`, `maddeler`, `bolumler`, `taahhut`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `users` WHERE `rol` = 'sahip' ORDER BY `id` LIMIT 1), 'ASANSÖR (İNSAN / YÜK) GÜVENLİ ÇALIŞMA TALİMATI', 'is_makineleri', 'Asansör (İnsan / Yük)', 1, 'YZ-TLM-007', 'Yapay zekâ taslağı — uzman tarafından gözden geçirilmeli', '[]', '[]', '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, bina ve tesislerde kullanılan insan ve yük asansörlerinin güvenli kullanımını, periyodik kontrollerini ve bakım-onarım süreçlerinde alınacak iş sağlığı ve güvenliği tedbirlerini kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"TS EN 397 standardına uygun çene bantlı endüstriyel emniyet bareti kullanılmalıdır.\",\"TS EN ISO 20345 standardına uygun S3 çelik burunlu ve kaymaz tabanlı iş ayakkabısı giyilmelidir.\",\"TS EN 388 standardına uygun mekanik risklere karşı koruyucu eldiven takılmalıdır.\",\"Kuyu içi ve kabin üstü çalışmalarında TS EN 361 standardına uygun tam vücut emniyet kemeri kullanılmalıdır.\",\"Bakım ve denetim esnasında TS EN 166 standardına uygun emniyet gözlüğü takılmalıdır.\",\"Gürültülü alanlardaki bakımlarda TS EN 352-2 standardına uygun kulak tıkacı veya kulaklık kullanılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Asansörün periyodik kontrol etiketinin (yeşil etiket) geçerliliği kontrol edilmelidir.\",\"Kabin içi aydınlatma ve acil durum aydınlatma sistemlerinin çalışırlığı test edilmelidir.\",\"Kabin içi acil haberleşme butonu ve alarm sisteminin aktif olduğu doğrulanmalıdır.\",\"Kat kapılarının mekanik ve kilit sistemleri ile fotosellerin çalışması denetlenmelidir.\",\"Asansör taşıma kapasitesi (kg ve kişi sayısı) bilgilendirme levhasının yerinde olduğu kontrol edilmelidir.\",\"Kabin tabanı ile kat seviyesi hizalamasının doğru yapıldığı doğrulanmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Asansörün etiketinde belirtilen azami yük ve kişi sayısı kapasitesi kesinlikle aşılmamalıdır.\",\"Yük asansörlerinde malzeme kabin merkezine dengeli yüklenmeli ve devrilmeye karşı sabitlenmelidir.\",\"Otomatik kapıların kapanması el, ayak veya malzeme ile engellenmemelidir.\",\"Kabin hareket halindeyken zıplama veya kabin dengesini bozacak hareketlerden kaçınılmalıdır.\",\"Yük yükleme ve boşaltma esnasında kabin ile kat eşiği arasındaki boşluğa dikkat edilmelidir.\",\"Kabin içi acil stop butonu yalnızca tehlike ve acil durum anında kullanılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Bakım ve onarım işlemleri yalnızca yetkili ve sertifikalı asansör bakım servisi tarafından yürütülmelidir.\",\"Bakım öncesinde EKED (Etiketleme-Kilitleme-Emniyete Alma-Denetleme) prosedürü uygulanarak ana güç kesilmelidir.\",\"Kuyu içi veya kabin üstü çalışmasında asansör kumandası REVİZYON moduna alınmalıdır.\",\"Tüm kat kapılarına \'BAKIM VAR - KULLANMAYINIZ\' uyarı levhaları ve emniyet şeritleri asılmalıdır.\",\"Bakım bitiminde tüm koruyucu kapaklar ve güvenlik devreleri tekrar aktif hale getirilmelidir.\",\"Makine dairesi ve kuyu dibi temizlenerek giriş kapıları kilitli tutulmalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Kırmızı etiketli (kullanımı tehlikeli) asansörlerin işletime alınması ve kullanılması kesinlikle yasaktır.\",\"Yangın, deprem ve afet anlarında asansörlerin tahliye amacıyla kullanılması yasaktır.\",\"İnsan asansörleriyle ağır ve dengesiz yük, yük asansörleriyle yetkisiz yolcu taşınması yasaktır.\",\"Asansör kuyu dibinde veya makine dairesinde atık ve malzeme depolanması yasaktır.\",\"Kat kapısı kilit mekanizmalarına dışarıdan yetkisiz müdahale yapılması yasaktır.\",\"Asansör kabini kat seviyesinde değilken kapı zorlanarak açılmaya çalışılmamalıdır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Kabinde mahsur kalma durumunda sakin kalınmalı ve acil durum haberleşme butonuna basılarak yardım istenmelidir.\",\"Mahsur kalan kişileri kurtarma müdahalesi sadece eğitimli yetkili personel veya itfaiye tarafından yapılmalıdır.\",\"Yetkisiz kişilerin kapı kilit anahtarı kullanarak kurtarma yapmaya çalışması engellenmelidir.\",\"Anormal ses, sarsıntı veya durma hatası algılandığında asansör derhal durdurulup yetkililere haber verilmelidir.\",\"Arızalanan asansörün ana şalteri kapatılmalı ve üzerine arıza bilgi levhası asılmalıdır.\",\"Meydana gelen tüm arıza, kaza ve ramak kalay olaylar derhal İSG birimine ve bina yönetimine bildirilmelidir.\"]}]', 'Bu talimatı okudum, anladım ve iş sağlığı ve güvenliği kurallarına uygun şekilde çalışacağımı kabul ederim.', NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'Asansör (İnsan / Yük)');

INSERT INTO `talimat_sablonlari` (`user_id`, `baslik`, `kategori`, `ekipman_tipi`, `yz_taslak`, `dokuman_no`, `aciklama`, `kkdler`, `maddeler`, `bolumler`, `taahhut`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `users` WHERE `rol` = 'sahip' ORDER BY `id` LIMIT 1), 'KALDIRMA AKSESUARLARI (SAPAN, ZİNCİR, HALAT, MAPA) GÜVENLİ ÇALIŞMA TALİMATI', 'is_makineleri', 'Kaldırma Aksesuarları (sapan, zincir, halat, mapa)', 1, 'YZ-TLM-008', 'Yapay zekâ taslağı — uzman tarafından gözden geçirilmeli', '[]', '[]', '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, sapan, zincir, çelik halat ve mapa gibi kaldırma aksesuarlarının TS EN 13414 ve TS EN 818 standartları ile 6331 sayılı İş Sağlığı ve Güvenliği Kanunu çerçevesinde güvenli kullanımını, periyodik kontrollerini ve bakım esaslarını belirlemek amacıyla hazırlanmıştır.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Mekanik risklere ve kesilmelere karşı koruyucu iş eldiveni (TS EN 388) kullanılmalıdır.\",\"Darbe ve ezilmelere karşı çelik burunlu emniyet ayakkabısı (TS EN ISO 20345) giyilmelidir.\",\"Baş yaralanmalarını önlemek amacıyla endüstriyel baret (TS EN 397) takılmalıdır.\",\"Yüksekte yürütülen sapancı ve işaretçi çalışmalarında tam vücut emniyet kemeri (TS EN 361) kullanılmalıdır.\",\"Gözleri uçuşan parçacıklardan korumak için koruyucu gözlük (TS EN 166) takılmalıdır.\",\"Saha çalışmasında yüksek görünürlük sağlamak için ikaz yeleği (TS EN ISO 20471) giyilmelidir.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Kaldırma aksesuarının güvenli çalışma yükü (WLL) etiketi ve periyodik kontrol rengi kontrol edilmelidir.\",\"Çelik halat sapanlarda ezilme, kopuk tel, korozyon veya kuş yuvalanması deformasyonu incelenmelidir.\",\"Zincir sapan baklalarında aşınma, çatlak, uzama veya TS EN 818 standart dışı deformasyon kontrol edilmelidir.\",\"Mapaların pimi, diş yapısı ve emniyet kopilyasının eksiksiz ve uygun boyutta olduğu doğrulanmalıdır.\",\"Bez ve dokuma sapanlarda lif kopması, kesik, yanık veya kimyasal yıpranma kontrol edilmelidir.\",\"Kaldırılacak yükün ağırlığı ve ağırlık merkezi belirlenerek uygun açı ve kapasitede aksesuar seçilmelidir.\",\"Keskin kenarlı yüklerde sapanların zedelenmesini önlemek için uygun köşe koruyucu aparatlar yerleştirilmelidir.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Sapan açıları dikkate alınmalı, sapan kolları arasındaki tepe açısı 120 dereceyi kesinlikle geçmemelidir.\",\"Kancaya takılan sapan halkalarının emniyet mandalını tam kapatacak şekilde oturduğu doğrulanmalıdır.\",\"Mapalar tam torkunda sıkılmalı ve eksenel olmayan yan yüklemelere maruz bırakılmamalıdır.\",\"Yük kaldırılırken sapan gerginliği kademeli olarak artırılmalı, ani kaldırma ve boşlama yapılmamalıdır.\",\"Yükün salınımını önlemek için kılavuz halatı kullanılmalı, yüke doğrudan elle müdahale edilmemelidir.\",\"Kaldırma esnasında aksesuarların birbiri üstüne biniş yapması veya burulması önlenmelidir.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Kullanım sonrası sapanlar, zincirler ve mapalar kir, yağ ve nemden arındırılarak temizlenmelidir.\",\"Aksesuarlar doğrudan güneş ışığı almayan, kuru ve korumalı alanlardaki özel askılıklarda muhafaza edilmelidir.\",\"Hasarlı, etiket bilgisi okunaksız veya standart dışı tespit edilen aksesuarlar derhal kullanımdan çekilmelidir.\",\"Kullanım dışı bırakılan aksesuarlara \'KULLANIMI TEHLİKELİDİR\' etiketi takılarak EKED (kilitleme-etiketleme) uygulanmalıdır.\",\"Çelik halat ve zincir aksesuarlar imalatçı talimatlarına uygun olarak periyodik yağlama işlemine tabi tutulmalıdır.\",\"Aksesuarların yılda en az bir kez yetkili uzman tarafından periyodik kontrollerinin yapılması sağlanmalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Güvenli çalışma yükü (WLL) etiketi bulunmayan veya okunamayan aksesuarları kullanmak yasaktır.\",\"Kopuk tel sayısı sınırını aşmış çelik halatları ve baklalarında uzama olan zincirleri kullanmak yasaktır.\",\"Sapanlara düğüm atmak, cıvata ile zincir boyu kısaltmak veya kaynaklı tamirat yapmak yasaktır.\",\"Hasarlı, dişleri bozulmuş veya pimi orijinal olmayan mapaları kullanmak yasaktır.\",\"Sapan kolları arasında 120 dereceden fazla açı oluşturacak şekilde kaldırma yapmak yasaktır.\",\"Keskin kenarlı yüklere koruyucu ped veya aparat takmadan sapan bağlamak yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Aksesuar kayması veya deformasyon riski görüldüğünde çalışma derhal durdurulmalıdır.\",\"Tehlikeli durum ve aksesuar arızaları vakit kaybetmeksizin birim amirine ve İSG birimine bildirilmelidir.\",\"Yük düşmesi veya devrilmesi durumunda alan derhal emniyet şeridine alınarak erişim kısıtlanmalıdır.\",\"Yaralanmalı kazalarda ilk yardım müdahalesi yapılarak 112 Acil Çağrı Merkezi bilgilendirilmelidir.\",\"Kazaya veya tehlikeye neden olan aksesuar ve olay yeri inceleme tamamlanana kadar korunmalıdır.\"]}]', 'Bu talimatı okudum, anladım ve iş sağlığı ve güvenliği kurallarına uygun şekilde çalışacağımı kabul ederim.', NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'Kaldırma Aksesuarları (sapan, zincir, halat, mapa)');

INSERT INTO `talimat_sablonlari` (`user_id`, `baslik`, `kategori`, `ekipman_tipi`, `yz_taslak`, `dokuman_no`, `aciklama`, `kkdler`, `maddeler`, `bolumler`, `taahhut`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `users` WHERE `rol` = 'sahip' ORDER BY `id` LIMIT 1), 'SEYYAR YÜK KALDIRMA LİFTİ (SEPETLİ VİNÇ / MOBİLYA ASANSÖRÜ) GÜVENLİ ÇALIŞMA TALİMATI', 'is_makineleri', 'Seyyar Yük Kaldırma Lifti (Sepetli Vinç / Mobilya Asansörü)', 1, 'YZ-TLM-009', 'Yapay zekâ taslağı — uzman tarafından gözden geçirilmeli', '[]', '[]', '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, seyyar yük kaldırma liftinin (sepetli vinç\\/mobilya asansörü) TS ISO 9927-1 standardı ile 6331 sayılı İş Sağlığı ve Güvenliği Kanunu\'na uygun olarak güvenli kullanımını, periyodik kontrollerini ve bakım esaslarını kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Baret (Çene bantlı - EN 397)\",\"Düşme Durdurucu Tam Vücut Emniyet Kemeri ve Lanyard (EN 361 \\/ EN 355 \\/ EN 358)\",\"Kaymayı Önleyici Çelik Burunlu İş Ayakkabısı (EN ISO 20345)\",\"Mekanik Risklerden Koruyucu İş Eldiveni (EN 388)\",\"Çapak ve Toza Karşı Koruyucu Gözlük (EN 166)\",\"Yüksek Sesli Ortamlarda Kulak Koruyucu (EN 352-2)\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Operatörün eğitimli ve ehliyetli olduğu doğrulanmalı, ekipmanın periyodik muayene etiketinin güncelliği kontrol edilmelidir.\",\"Destek ayakları (outrigger) ve takozlar sağlam zemine tam açılmalı, aracın terazi dengesi kontrol edilmelidir.\",\"Aşırı yük sınırlayıcının ve en alt\\/en üst nokta aşırı çekme\\/sarma önleyici limit anahtarlarının alarmla sistemi durdurduğu test edilmelidir.\",\"Acil durdurma butonlarının çalışırlığı denetlenmeli ve yalnız elle sıfırlanabildiği doğrulanmalıdır.\",\"Çelik halatlarda tel kopması, ezilme ve korozyon; döner tabla bağlantıları ve hidrolik silindir\\/hortumlarda kaçak kontrolü yapılmalıdır.\",\"Sepet yan korumaları, kapı kilitleri, yük ve emniyet işaretleme levhaları ile kaldırma yük tablosunun (ağırlık-menzil) görünürlüğü denetlenmelidir.\",\"Yük bağlama elemanlarının (sapan, zincir) sertifikalı ve hasarsız olduğu teyit edilmelidir.\",\"Çalışma sahasındaki enerji hatlarına güvenli yaklaşma mesafesi korunmalı ve alan emniyet şeridi ile kapatılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Sepetteki personel, tam vücut emniyet kemerini sepet içindeki onaylı ankraj noktasına bağlamalıdır.\",\"Kaldırma yük tablosunda belirtilen maksimum güvenli çalışma yükü ve menzil sınırları kesinlikle aşılmamalıdır.\",\"Teleskopik bom hareketleri, dönüşler, frenleme ve kavrama işlemleri sarsıntısız ve kademeli yapılmalıdır.\",\"Rüzgar hızı güvenli çalışma limitini (12.5 m\\/s) aştığında veya fırtınalı havalarda çalışma derhal durdurulmalıdır.\",\"Sepet kapısı çalışma esnasında daima kilitli tutulmalı ve çalışma alanının altına yetkisiz kişilerin girmesi engellenmelidir.\",\"Kaldırma ve indirme sırasında işaretçi\\/sapancı ile kesintisiz haberleşme sağlanmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma tamamlandığında bom tamamen toplanmalı, sepet emniyetli park konumuna indirilmelidir.\",\"Destek ayakları toplanmalı, pim ve kilit mekanizmaları emniyete alınmalıdır.\",\"Araç motoru kapatılmalı, anahtar çekilmeli ve yetkisiz kullanımı önlemek için kumanda panosu kilitlenmelidir.\",\"Temizlik ve bakım faaliyetleri sırasında hidrolik\\/elektrik enerjisi kesilmeli, Tehlikeli Enerji Kontrolü (EKED\\/LOTO) uygulanmalıdır.\",\"Günlük bakım denetimleri tamamlanarak tespit edilen hususlar operatör günlük kontrol formuna işlenmelidir.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Yetkisiz, eğitimsiz ve belgesiz kişilerin lifti kullanması kesinlikle yasaktır.\",\"Sepet korkuluklarına tırmanmak, sepet üzerine merdiven veya iskele koyarak yüksekliği artırmaya çalışmak yasaktır.\",\"Destek ayakları kurulmadan veya zemin meyli uygun değilken kaldırma ve bom hareketleri yapmak yasaktır.\",\"Aşırı yük limitörünü, emniyet anahtarlarını ve acil stop butonlarını devre dışı bırakarak çalışmak yasaktır.\",\"Kaldırma halatlarına, boom yapısına veya sepet tabanına kapasite üzerinde dengesiz yük koymak yasaktır.\",\"Sepette personel veya serbest yük varken aracı yürütmek veya konum değiştirmek yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma sırasında anormal ses, hidrolik kaçak veya sarsıntı hissedildiğinde acil stop butonuna basılarak sistem derhal durdurulmalıdır.\",\"Sepette mahsur kalma veya güç kesintisi durumunda, eğitimli personel tarafından manuel acil indirme valfi kullanılarak sepet emniyetle aşağı çekilmelidir.\",\"Meydana gelen her türlü arıza, kaza veya ramak kala olayı derhal İş Güvenliği Uzmanına ve Saha Sorumlusuna bildirilmelidir.\",\"Arızalı lift üzerine \'ARIZALIDIR - KULLANILMAZ\' etiketi asılmalı ve yetkili servis onayı olmadan tekrar işletime alınmamalıdır.\"]}]', 'Bu talimatı okudum, anladım ve iş sağlığı ve güvenliği kurallarına uygun şekilde çalışacağımı kabul ederim.', NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'Seyyar Yük Kaldırma Lifti (Sepetli Vinç / Mobilya Asansörü)');

INSERT INTO `talimat_sablonlari` (`user_id`, `baslik`, `kategori`, `ekipman_tipi`, `yz_taslak`, `dokuman_no`, `aciklama`, `kkdler`, `maddeler`, `bolumler`, `taahhut`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `users` WHERE `rol` = 'sahip' ORDER BY `id` LIMIT 1), 'HİDROFOR & GENLEŞME DEPOSU GÜVENLİ ÇALIŞMA TALİMATI', 'is_makineleri', 'Hidrofor & Genleşme Deposu', 1, 'YZ-TLM-010', 'Yapay zekâ taslağı — uzman tarafından gözden geçirilmeli', '[]', '[]', '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, hidrofor ve genleşme deposunun TS EN 13831 standardına ve 6331 sayılı İSG Kanunu\'na uygun olarak emniyetli kullanımı, periyodik kontrolleri ve bakımı sırasında alınması gereken iş sağlığı ve güvenliği önlemlerini kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Mekanik risklere karşı koruyucu iş ayakkabısı (TS EN ISO 20345) giyilmelidir.\",\"Gürültülü çalışma ortamında işitme koruyucu kulaklık (TS EN 352-1) kullanılmalıdır.\",\"Sıvı ve basınçlı hava sıçramalarına karşı koruyucu iş gözlüğü (TS EN 166) takılmalıdır.\",\"Mekanik risklere dayanıklı koruyucu iş eldiveni (TS EN 388) kullanılmalıdır.\",\"Elektrik panosu müdahalelerinde yalıtkan eldiven (TS EN 60903) kullanılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Hidrofor ve genleşme deposunun yıllık periyodik kontrol etiketleri ve kontrol raporları denetlenmelidir.\",\"Manometrelerin sağlamlığı, sıfır noktası ayarı ve geçerli kalibrasyon durumları kontrol edilmelidir.\",\"Emniyet ventilinin mühürlü, temiz ve çalışır durumda olduğu doğrulanmalıdır.\",\"Membranlı genleşme deposunun ön gaz basıncı üretici değerlerine uygunluk açısından ölçülmelidir.\",\"Elektrik bağlantıları, topraklama hattı ve kaçak akım rölesinin işlevselliği kontrol edilmelidir.\",\"Depo gövdesinde sızıntı, paslanma, korozyon veya yapısal deformasyon bulunmadığından emin olunmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Sistem çalışma basıncı, tank etiketi üzerinde belirtilen maksimum çalışma basıncını (PS) kesinlikle aşmamalıdır.\",\"Pompa devreye girme ve çıkma basınç aralıkları basınç şalteri üzerinden düzenli olarak izlenmelidir.\",\"Emniyet ventilinin tahliye mekanizması sıkışmalara karşı periyodik olarak elle kontrol edilmelidir.\",\"Çalışma sırasında hidrofor ve boru tesisatındaki anormal ses, titreşim ve su sızıntıları takip edilmelidir.\",\"Basınç altındaki genleşme deposuna dışarıdan darbe vurulmamalı ve üzerine yük istiflenmemelidir.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Bakım ve onarım işlemlerinden önce hidroforun ana elektrik beslemesi kesilmeli ve Kilitleme-Etiketleme (EKED) uygulanmalıdır.\",\"Depo içerisindeki basınçlı su ve hava, tahliye vanaları kullanılarak tamamen boşaltılmalıdır.\",\"Manometre sıfır değerini göstermeden tank üzerinde hiçbir mekanik söküm veya civata gevşetme işlemi yapılmamalıdır.\",\"Membran değişimi ve hava basma işlemleri yetkili teknik personel tarafından gerçekleştirilmelidir.\",\"Bakım tamamlandıktan sonra koruyucu muhafazalar ve emniyet donanımları takılmadan sistem devreye alınmamalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Emniyet ventilinin iptal edilmesi, ayarının değiştirilmesi veya hat üzerine kapatma vanası konulması yasaktır.\",\"Basınç altındaki depo gövdesine ve bağlantı borularına kaynak, kesme veya delme işlemi yapmak yasaktır.\",\"Periyodik kontrol süresi dolmuş veya kontrolü yapılmamış genleşme depolarını çalıştırmak yasaktır.\",\"Yetkisiz kişilerin hidrofor odasına girmesi ve basınç şalteri ayarlarına müdahale etmesi yasaktır.\",\"Tankın etiketinde belirtilen maksimum çalışma sıcaklığı ve basınç limitlerinin üzerinde işletim yapmak yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Aşırı basınç yükselmesi veya emniyet ventilinin açmaması durumunda acil stop butonuna basılarak sistem durdurulmalıdır.\",\"Tank gövdesinde deformasyon, çatlak veya ani kaçak tespiti halinde tesisat emniyetli şekilde tahliye edilmelidir.\",\"Elektrik panosunda ark, kıvılcım veya koku algılandığında ana şalter derhal kapatılmalıdır.\",\"Meydana gelen tüm arıza, sızıntı ve ramak kala olaylar İSG Birimi ve Teknik Bakım Servisine bildirilmelidir.\",\"Elektrik kaynaklı yangın durumunda su ile müdahale edilmemeli, CO2 veya kuru kimyevi tozlu yangın söndürücüler kullanılmalıdır.\"]}]', 'Bu talimatı okudum, anladım ve iş sağlığı ve güvenliği kurallarına uygun şekilde çalışacağımı kabul ederim.', NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'Hidrofor & Genleşme Deposu');

INSERT INTO `talimat_sablonlari` (`user_id`, `baslik`, `kategori`, `ekipman_tipi`, `yz_taslak`, `dokuman_no`, `aciklama`, `kkdler`, `maddeler`, `bolumler`, `taahhut`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `users` WHERE `rol` = 'sahip' ORDER BY `id` LIMIT 1), 'BUHAR KAZANI GÜVENLİ ÇALIŞMA TALİMATI', 'is_makineleri', 'Buhar Kazanı', 1, 'YZ-TLM-011', 'Yapay zekâ taslağı — uzman tarafından gözden geçirilmeli', '[]', '[]', '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, buhar kazanının TS 2025 ve TS EN 12953 standartlarına uygun şekilde güvenli kullanımını, periyodik kontrollerini, işletilmesini ve bakım aşamalarındaki iş sağlığı ve güvenliği kurallarını kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Isıya ve mekanik risklere dayanıklı koruyucu eldiven (EN 407 \\/ EN 388) kullanılmalıdır.\",\"Sıçramalara ve çapaklara karşı yan korumalı emniyet gözlüğü (EN 166) takılmalıdır.\",\"Çelik burunlu ve kaymaz tabanlı iş emniyet ayakkabısı (EN ISO 20345) giyilmelidir.\",\"Yüksek gürültü seviyesine sahip alanlarda kulak koruyucu (EN 352-2) kullanılmalıdır.\",\"Isıya ve aleve dayanıklı koruyucu iş elbisesi (EN ISO 11612) giyilmelidir.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Operatör yetkisi ve cihazın periyodik kontrol etiketinin geçerliliği kontrol edilmelidir.\",\"Su seviye göstergeleri, manometre ve emniyet valflerinin çalışırlığı kontrol edilmelidir.\",\"Besi suyu deposu su seviyesi ve yumuşatma sisteminin uygunluğu doğrulanmalıdır.\",\"Yakıt besleme hatları ve brülör bağlantılarında sızıntı kontrolü yapılmalıdır.\",\"Baca klapeleri, duman kanalları ve kazan dairesi havalandırma menfezleri açık tutulmalıdır.\",\"Emniyet blöfü ve otomatik seviye kontrol sistemlerinin testleri gerçekleştirilmelidir.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Kazan işletme basıncı, TS 2025 standardında belirlenen maksimum izin verilen basınç değerini aşmamalıdır.\",\"Su seviyesi çalışma boyunca takip edilmeli, emniyet alt sınırının altına düşmesine izin verilmemelidir.\",\"Emniyet valflerinin tutukluk yapmaması için vardiya başında manuel blöf kontrolü yapılmalıdır.\",\"Dip ve yüzey blöf işlemleri işletme talimatına uygun olarak aşamalı şekilde yapılmalıdır.\",\"Brülörün alev kontrolü ve yanma kalitesi izlenmeli, patlamalı ateşlemelere izin verilmemelidir.\",\"Kazan dairesi havalandırma fanları çalışma süresince kesintisiz devrede tutulmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Kazan kapatıldıktan sonra ana besleme şalteri indirilerek EKED (Etiketleme-Kilitleme) uygulanmalıdır.\",\"Bakım öncesinde kazan iç basıncı tamamen sıfırlanmalı ve manometreden doğrulanmalıdır.\",\"Kazan soğumadan ve basınç tamamen düşmeden blöf vanaları ve gözetleme kilitleri açılmamalıdır.\",\"Yakıt ve gaz vanaları kapatılarak emniyet kilitleri takılmalı, hat emniyete alınmalıdır.\",\"Kazan içi temizlik ve denetim çalışmalarında 24 Volt alçak gerilim aydınlatması kullanılmalıdır.\",\"Yapılan tüm bakım, temizlik ve test verileri kazan işletme defterine eksiksiz kaydedilmelidir.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Sanayi Kazanı İşletme Belgesi bulunmayan kişilerin kazanı çalıştırması ve müdahale etmesi yasaktır.\",\"Basınç altındaki kazana, boru hatlarına veya vanalara kaynak ve darbeli müdahale yapılması yasaktır.\",\"Emniyet valflerinin ayarlarını değiştirmek, ağırlık eklemek veya valfleri körlemek yasaktır.\",\"Susuz kalmış aşırı ısınmış kazana aniden soğuk besi suyu basılması kesinlikle yasaktır.\",\"Kazan dairesi içinde yanıcı, parlayıcı malzeme depolanması ve açık alevle yaklaşılması yasaktır.\",\"Otomatik emniyet röleleri ve seviye denetleyicileri baypas edilerek kazan çalıştırılamaz.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Kazanın susuz kaldığı fark edildiğinde brülör derhal kapatılmalı, su verilmemeli ve sistem soğumaya bırakılmalıdır.\",\"Aşırı basınç yükselmesinde brülör acil stop butonuna basılarak yakıt akışı derhal kesilmelidir.\",\"Yakıt veya gaz kaçağı durumunda ana vanalar kapatılmalı, ortam havalandırılmalı ve şalterlere dokunulmamalıdır.\",\"Kazan dairesinde yangın çıkması halinde acil durum alarmı verilerek 112 Acil Çağrı Merkezi aranmalıdır.\",\"Tespit edilen her türlü arıza, anormal ses veya sızıntı derhal İSG Birimine ve İşletme Sorumlusuna bildirilmelidir.\"]}]', 'Bu talimatı okudum, anladım ve iş sağlığı ve güvenliği kurallarına uygun şekilde çalışacağımı kabul ederim.', NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'Buhar Kazanı');

INSERT INTO `talimat_sablonlari` (`user_id`, `baslik`, `kategori`, `ekipman_tipi`, `yz_taslak`, `dokuman_no`, `aciklama`, `kkdler`, `maddeler`, `bolumler`, `taahhut`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `users` WHERE `rol` = 'sahip' ORDER BY `id` LIMIT 1), 'KALORİFER KAZANI / SICAK SU KAZANI GÜVENLİ ÇALIŞMA TALİMATI', 'is_makineleri', 'Kalorifer Kazanı / Sıcak Su Kazanı', 1, 'YZ-TLM-012', 'Yapay zekâ taslağı — uzman tarafından gözden geçirilmeli', '[]', '[]', '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, kalorifer ve sıcak su kazanlarının güvenli şekilde işletilmesi, periyodik bakımı ve olası iş kazaları ile meslek hastalıklarının önlenmesine yönelik uygulama esaslarını kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Isıya ve mekanik risklere karşı koruyucu iş eldiveni (EN 388, EN 407) kullanılmalıdır.\",\"Çelik burunlu ve kaymaz tabanlı iş güvenliği ayakkabısı (EN ISO 20345) giyilmelidir.\",\"Çapak ve sıvı sıçramalarına karşı koruyucu iş gözlüğü (EN 166) takılmalıdır.\",\"Gürültü seviyesinin 85 dB(A) değerini aştığı durumlarda kulak koruyucu (EN 352-2) kullanılmalıdır.\",\"Temizlik, kül alma veya yakıt yükleme işlerinde parçacık filtreli toz maskesi (EN 149 FFP2) takılmalıdır.\",\"Isıya ve aleve dayanıklı koruyucu iş elbisesi (EN ISO 11612) giyilmelidir.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Kazanın yıllık periyodik kontrol etiketinin güncel olduğu teyit edilmelidir.\",\"Su seviye göstergeleri, manometreler ve emniyet ventillerinin çalışırlığı denetlenmelidir.\",\"Kazan dairesinin tabii ve cebri havalandırma sistemlerinin açık olduğu kontrol edilmelidir.\",\"Yakıt hatlarında, vanalarda ve brülör bağlantılarında gaz veya yakıt kaçağı denetimi yapılmalıdır.\",\"Genleşme tankı ön basıncı ve tesisattaki su miktarı uygun seviyede olmalıdır.\",\"Kazan dairesinde yanıcı, patlayıcı ve yabancı maddelerin bulunmadığından emin olunmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Kazan çalışma basıncı ve su sıcaklığı manometre ile termometreden sürekli takip edilmelidir.\",\"Alev gözetleme camından brülörün yanma durumu ve alev boyu düzenli olarak izlenmelidir.\",\"Su seviyesi emniyet sınırının altına düştüğünde brülör otomatik olarak durmalı, durmazsa elle müdahale edilmelidir.\",\"Sıcak yüzeylerle teması önlemek için yalıtımsız hatlara ve kazan gövdesine koruyucusuz dokunulmamalıdır.\",\"Çalışma esnasında kazan dairesi kapıları kilitlenmemeli ve kaçış yolları açık tutulmalıdır.\",\"Emniyet ventillerinin manuel tahliye kolları aşırı basınç oluşmadan dönemsel olarak test edilmelidir.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Kazan kapatılacağında öncelikle brülör durdurulmalı, kazan sıcaklığı güvenli seviyeye düşene kadar sirkülasyon pompaları çalıştırılmalıdır.\",\"Bakım ve onarım işlemlerinden önce elektrik beslemesi kesilmeli ve Etiketleme-Kilitleme (EKED\\/LOTO) uygulanmalıdır.\",\"Kazan içi basınç tamamen sıfırlanmadan ve su sıcaklığı düşmeden blöf ve boşaltma vanaları açılmamalıdır.\",\"Kazan gövde içi veya baca temizliği yapılmadan önce sistem havalandırılmalı ve gaz birikimi olmadığından emin olunmalıdır.\",\"Dip blöf işlemi basınç düşük seviyedeyken ve kademeli olarak gerçekleştirilmelidir.\",\"Periyodik bakımlar yetkili servisler ve uzman personeller tarafından kaydedilerek yapılmalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Susuz kalan veya aşırı ısınan kazana kesinlikle ani soğuk su beslemesi yapılmamalıdır.\",\"Emniyet valflerinin ve basınç otomatiğinin ayarları yetkisiz kişilerce değiştirilmemeli veya kilitlenmemelidir.\",\"Kazan dairesinde sigara içilmemeli, açık ateş yakılmamalı ve kıvılcım çıkaran aletler kullanılmamalıdır.\",\"Kazan dairesi depo, ardiye veya soyunma odası gibi amaç dışı kullanılmamalıdır.\",\"Yetkisiz ve İş İşletme Eğitimi almamış personelin kazan dairesine girmesine ve müdahale etmesine izin verilmemelidir.\",\"Basınç altındaki hatlarda veya gövdede kaynak, sıkma ve mekanik müdahale yapılmamalıdır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Aşırı basınç artışı veya anormal ses duyulduğunda acil stop butonuna basılarak brülör derhal kapatılmalıdır.\",\"Gaz kokusu veya sızıntısı hissedildiğinde ana gaz vanası kapatılmalı, elektrik anahtarlarına dokunulmadan ortam havalandırılmalıdır.\",\"Yangın durumunda ilk olarak ana yakıt ve elektrik besleme vanaları\\/şalterleri kapatılmalıdır.\",\"Her türlü arıza, su kaçağı ve emniyet bileşeni arızası derhal İş Güvenliği Uzmanı ve Teknik Bakım Sorumlusuna bildirilmelidir.\",\"Acil durum müdahalesi sonrasında yetkili teknik personel onay vermeden cihaz yeniden işletime alınmamalıdır.\"]}]', 'Bu talimatı okudum, anladım ve iş sağlığı ve güvenliği kurallarına uygun şekilde çalışacağımı kabul ederim.', NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'Kalorifer Kazanı / Sıcak Su Kazanı');

INSERT INTO `talimat_sablonlari` (`user_id`, `baslik`, `kategori`, `ekipman_tipi`, `yz_taslak`, `dokuman_no`, `aciklama`, `kkdler`, `maddeler`, `bolumler`, `taahhut`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `users` WHERE `rol` = 'sahip' ORDER BY `id` LIMIT 1), 'KIZGIN YAĞ KAZANI GÜVENLİ ÇALIŞMA TALİMATI', 'is_makineleri', 'Kızgın Yağ Kazanı', 1, 'YZ-TLM-013', 'Yapay zekâ taslağı — uzman tarafından gözden geçirilmeli', '[]', '[]', '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, kızgın yağ kazanının güvenli bir şekilde çalıştırılmasını, işletilmesini, bakımını ve olası tehlikelere karşı alınacak önlemleri kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Yüksek sıcaklığa ve sıçramalara dayanıklı koruyucu gözlük veya yüz siperliği (EN 166) kullanılmalıdır.\",\"Isıya dayanıklı ve kimyasal dirençli koruyucu eldiven (EN 407 \\/ EN 388) takılmalıdır.\",\"Isıya ve kıvılcıma dayanıklı, statik elektrik önleyici iş elbisesi (EN ISO 11612) giyilmelidir.\",\"Kaymaz ve ısıya dayanıklı tabanlı emniyet ayakkabısı (EN ISO 20345) kullanılmalıdır.\",\"Gerekli havalandırma sağlanamadığı durumlarda organik buhar ve gaz filtreli yarım yüz maskesi (EN 140 \\/ EN 14387) takılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Kazanın periyodik kontrol etiketleri, emniyet valfleri ve basınç göstergelerinin geçerliliği kontrol edilmelidir.\",\"Termik yağ seviyesi, genleşme deposu ve sirkülasyon pompalarının çalışma durumu çalıştırılmadan önce denetlenmelidir.\",\"Sisteme giren yağın nemden arındırılmış olduğu ve tesisatta su birikintisi bulunmadığı doğrulanmalıdır.\",\"Brülör, yakıt hatları, baca klapeleri ve havalandırma kanallarının açık ve engelsiz olduğu denetlenmelidir.\",\"Kazan dairesindeki gaz algılama ve yangın söndürme sistemlerinin aktif durumda olduğu kontrol edilmelidir.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Kazan işletme sıcaklığı ve basıncı TS EN 12952 standartlarına ve imalatçı limitlerine uygun seviyede tutulmalıdır.\",\"Sirkülasyon pompaları durdurulmadan önce brülör kapatılmalı ve yağ sıcaklığının emniyetli seviyeye düşmesi beklenmelidir.\",\"Yağ sıcaklığı ve fark basınç değerleri düzenli aralıklarla manometre ve termometre üzerinden takip edilmelidir.\",\"Genleşme deposu sıcaklığı ve yağ genleşme miktarı çalışma boyunca sürekli gözlemlenmelidir.\",\"Sistemde kavitasyon veya anormal ses tespiti halinde çalışma derhal durdurulup kontrol sağlanmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Bakım ve onarım çalışmalarından önce kazan tamamen soğutulmalı ve sistem basıncı sıfırlanmalıdır.\",\"Elektrik ve yakıt besleme hatlarına Etiketleme-Kilitleme (EKED\\/LOTO) prosedürü uygulanmalıdır.\",\"Termik yağın nitelik analizi ve viskozite testleri periyodik olarak yetkili kurumlara yaptırılmalıdır.\",\"Filtre ve pislik tutucular sistem soğutulduktan sonra temizlenmeli veya değiştirilmelidir.\",\"Emniyet ventillerinin ve basınç şalterlerinin fonksiyonel testleri yetkili teknik personelce yapılmalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Yetkisiz ve belgesiz personelin kızgın yağ kazanına müdahale etmesi veya çalıştırması yasaktır.\",\"Kızgın yağ tesisatına ve genleşme deposuna hiçbir koşulda su veya nemli madde karıştırılmamalıdır.\",\"Emniyet valfleri, limit termostatlar ve basınç sensörleri devre dışı bırakılarak çalışılmamalıdır.\",\"Kazan dairesi içerisinde yanıcı, parlayıcı veya patlayıcı kimyasal maddeler depolanmamalıdır.\",\"Sistem basınç altındayken veya yüksek sıcaklıktayken vanalara sert darbe vurulmamalı ve rekor\\/flanş sökümü yapılmamalıdır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Aşırı sıcaklık, basınç yükselmesi veya yağ kaçağı durumunda acil stop butonuna basılarak sistem durdurulmalıdır.\",\"Yangın durumunda su kesinlikle kullanılmamalı, CO2 veya kuru kimyevi tozlu yangın söndürücülerle müdahale edilmelidir.\",\"Her türlü sızıntı, koku veya anormal ses durumu derhal iş güvenliği uzmanına ve teknik sorumlulara bildirilmelidir.\",\"Sıcak yağ teması veya yanık vakalarında acil ilk yardım uygulanmalı ve en yakın sağlık kuruluşuna haber verilmelidir.\"]}]', 'Bu talimatı okudum, anladım ve iş sağlığı ve güvenliği kurallarına uygun şekilde çalışacağımı kabul ederim.', NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'Kızgın Yağ Kazanı');

INSERT INTO `talimat_sablonlari` (`user_id`, `baslik`, `kategori`, `ekipman_tipi`, `yz_taslak`, `dokuman_no`, `aciklama`, `kkdler`, `maddeler`, `bolumler`, `taahhut`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `users` WHERE `rol` = 'sahip' ORDER BY `id` LIMIT 1), 'LPG / KRİYOJENİK SIVI GAZ DEPOSU GÜVENLİ ÇALIŞMA TALİMATI', 'is_makineleri', 'LPG / Kriyojenik Sıvı Gaz Deposu', 1, 'YZ-TLM-014', 'Yapay zekâ taslağı — uzman tarafından gözden geçirilmeli', '[]', '[]', '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, LPG ve kriyojenik sıvı gaz depolarının TS EN 12817 ve TS EN 13458 standartları ile 6331 sayılı İş Sağlığı ve Güvenliği Kanunu\'na uygun olarak emniyetli şekilde işletilmesini, dolumunu, bakımını ve periyodik kontrollerini kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Kriyojenik yanıklara ve aşırı soğuğa karşı koruyucu eldiven (TS EN 511) kullanılmalıdır.\",\"Sıvı gaz sıçraması ve sıçramalara karşı tam korumalı yüz siperliği veya koruyucu gözlük (TS EN 166) takılmalıdır.\",\"Statik elektrik yüklenmesini önleyen antistatik ve alev geciktirici koruyucu iş kıyafeti (TS EN 1149-5 \\/ TS EN ISO 11612) giyilmelidir.\",\"Elektrostatik deşarj sağlayan antistatik ve burnu çelik koruyuculu iş ayakkabısı (TS EN ISO 20345 S1P\\/S3) kullanılmalıdır.\",\"Gaz kaçağı olabilecek kapalı ortamlarda acil durumlar için uygun filtreli solunum koruyucu maske (TS EN 14387) hazır bulundurulmalıdır.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Depo sahasındaki statik topraklama hattı ve topraklama penseleri dolum öncesinde kontrol edilerek bağlantısı sağlanmalıdır.\",\"Tank üzerindeki manometre, emniyet valfleri, seviye göstergesi ve gaz algılama sensörlerinin çalışır durumda olduğu doğrulanmalıdır.\",\"Tank çevresinde tutuşturucu kaynak, açık ateş, sigara veya ex-proof olmayan ekipman bulunmadığı denetlenmelidir.\",\"Saha havalandırma sisteminin aktif olduğu ve ex-proof aydınlatma armatürlerinin çalıştığı kontrol edilmelidir.\",\"Acil kapatma vanaları (ESD) ile yangın söndürme sistemlerinin erişilebilir ve operasyonel olduğu teyit edilmelidir.\",\"Kriyojenik tesisat boru hatlarında, vanalarda ve bağlantı noktalarında kaçak, aşırı buzlanma veya mekanik hasar denetimi yapılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Gaz dolum veya boşaltım işlemi süresince tanker ile depolama tankı arasındaki statik topraklama bağlantısı kesintisiz sürdürülmelidir.\",\"İşletme basıncı ve sıcaklık değerleri TS EN 13458 standardında ve tank etiketinde belirtilen azami limitlerin üzerine çıkarılmamalıdır.\",\"Tesisat üzerindeki vanalar ve valfler ani koç darbesi oluşturmayacak şekilde yavaşça ve kademeli olarak açılıp kapatılmalıdır.\",\"Kriyojenik sıvı transferi esnasında hatlarda gaz sıkışmasını ve aşırı basınç oluşumunu önlemek için tahliye ventilleri gözetim altında tutulmalıdır.\",\"Gaz transferi boyunca yetkili operatör tank sahasını terk etmemeli ve dolum sürecini kesintisiz izlemelidir.\",\"Tank dolum seviyesi mevzuatta ve standartlarda belirtilen maksimum dolum limitinin (genellikle %85) üzerine geçirilmemelidir.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Dolum işlemi tamamlandığında transfer hortumları basınçsızlaştırıldıktan sonra emniyetli şekilde sökülüp muhafaza alanına alınmalıdır.\",\"Tank ve tesisat üzerinde yapılacak her türlü bakım, onarım ve temizlik öncesinde Kilitleme-Etiketleme (EKED\\/LOTO) prosedürü uygulanmalıdır.\",\"Depo tankının periyodik kontrolleri ve hidrostatik\\/tahribatsız muayene testleri TS EN 12817 standardına uygun olarak yetkili uzmanlara yaptırılmalıdır.\",\"Emniyet valflerinin periyodik testleri, bakımları ve kalibrasyon doğrulamaları zamanında tamamlanmalıdır.\",\"Kriyojenik tankların vakum performansı ve yalıtım hazneleri periyodik olarak kontrol edilerek kayıt altına alınmalıdır.\",\"Tesisattaki sızdırmazlık kontrolleri uygun köpük solüsyonu veya kalibre edilmiş gaz dedektörleri ile periyodik olarak tekrarlanmalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Depolama ve dolum sahasına yetkisiz kişilerin girmesi, müdahalede bulunması veya araç park etmesi kesinlikle yasaktır.\",\"Tank sahası içerisinde sigara içilmesi, açık alev kullanılması ve ex-proof olmayan cep telefonu\\/elektronik cihaz çalıştırılması yasaktır.\",\"Basınç altındaki kriyojenik ve LPG hatları üzerinde kesme, kaynak veya sıcak çalışma yapılması kesinlikle yasaktır.\",\"Donmuş veya yoğun buzlanmış vanalara pürmüz, açık alev veya darbe uygulayarak müdahale edilmesi yasaktır.\",\"Emniyet valflerinin önündeki blok vanaları kapalı konumda bırakmak veya güvenlik ekipmanlarını bypass etmek yasaktır.\",\"Kriyojenik sıvı gazlara ve soğuk hatlara koruyucu donanımsız yalın elle temas edilmesi kesinlikle yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Gaz kaçağı veya anormallik tespit edildiğinde derhal Acil Kapatma Butonuna (ESD) basılarak gaz akışı kesilmelidir.\",\"Sızıntı veya yangın durumunda acil durum alarmı devreye sokulmalı, saha derhal tahliye edilerek güvenli toplanma alanına geçilmelidir.\",\"Kriyojenik yanık veya gaz maruziyeti durumunda etkilenen personele ilk yardım uygulanmalı ve derhal 112 Acil Çağrı Merkezi aranmalıdır.\",\"Sistemde meydana gelen her türlü sızıntı, anormal basınç yükselmesi veya ekipman arızası İş Güvenliği Uzmanına ve Bakım Sorumlusuna bildirilmelidir.\",\"Yangın durumunda rüzgar arkaya alınarak ex-proof özellikteki kuru kimyevi tozlu veya CO2 yangın söndürücüler ile müdahale edilmelidir.\"]}]', 'Bu talimatı okudum, anladım ve iş sağlığı ve güvenliği kurallarına uygun şekilde çalışacağımı kabul ederim.', NOW(), NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `talimat_sablonlari` WHERE `ekipman_tipi` = 'LPG / Kriyojenik Sıvı Gaz Deposu');

-- Doğrulama: beklenen  yz_taslak = 14
SELECT COUNT(*) AS yz_taslak FROM `talimat_sablonlari` WHERE `ekipman_tipi` IS NOT NULL;
